const gui_font_t *gui_font_get(gui_font_id_t font)
{
    if ((unsigned)font >= sizeof fonts / sizeof fonts[0]) return NULL;
    return &fonts[font];
}

const gui_glyph_t *gui_font_glyph(const gui_font_t *font, unsigned character)
{
    if (!font || !font->glyphs || font->first > font->last) return NULL;
    if (character < font->first || character > font->last) {
        character = font == &fonts[GUI_FONT_TIMER] ? '-' : '?';
        if (character < font->first || character > font->last) return NULL;
    }
    return &font->glyphs[character - font->first];
}

size_t gui_fonts_bytes(void)
{
    return sizeof font_alpha + sizeof glyphs + sizeof fonts;
}

_Static_assert(sizeof font_alpha + sizeof glyphs + sizeof fonts <= 24576, "GUI font budget exceeded");
